type Config = { env: string; region: string };

function loadConfig(rawJson: string): Config {
  const raw: unknown = JSON.parse(rawJson);   // boundary: contain, don't trust
  if (
    typeof raw === "object" && raw !== null &&
    "env" in raw && typeof raw.env === "string" &&
    "region" in raw && typeof raw.region === "string"
  ) {
    return { env: raw.env, region: raw.region };
  }
  throw new Error("Invalid config payload");
}

